def increment_semver(version, part):
    parts = list(map(int, version.split('.')))
    if part == 'major':
        parts[0] += 1
        parts[1:] = [0, 0]
    elif part == 'minor':
        parts[1] += 1
        parts[2] = 0
    elif part == 'patch':
        parts[2] += 1
    return '.'.join(map(str, parts))
```

