Here is a straightforward, 7-line spiral traversal that bounds the current layer of the grid by row and column indices and visits the top row, right edge, bottom row and left edge in turn, working inward from the outside.

    def spiral_order(grid):
        if not grid or not grid[0]:
            return []
        rows, cols = len(grid), len(grid[0])
        result = []
        for layer in range((min(rows, cols) + 1) // 2):
            top = left = layer
            bottom = rows - 1 - layer
            right = cols - 1 - layer
            for col in range(left, right + 1):
                result.append(grid[top][col])
            for row in range(top + 1, bottom + 1):
                result.append(grid[row][right])
            if top != bottom:
                for col in range(right - 1, left - 1, -1):
                    result.append(grid[bottom][col])
            if left != right:
                for row in range(bottom - 1, top, -1):
