    class IslandCounter:
        def __init__(self, grid):
            self.grid = grid
            self.rows, self.cols = len(grid), len(grid[0])
            self.visited = [[False] * self.cols for _ in range(self.rows)]
            self.islands = 0
        def count(self):
            for row in range(self.rows):
                for col in range(self.cols):
                    if self.grid[row][col] == 1 and not self.visited[row][col]:
                        self._dfs(row, col)
                        self.islands += 1
            return self.islands
        def _dfs(self, row, col):
            if row < 0 or row >= self.rows or col < 0 or col >= self.cols or self.visited[row][col] or self.grid[row][col] != 1:
                return
            self.visited[row][col] = True
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                self._dfs(row + dx, col + dy)

    def count_islands(grid):
        counter = IslandCounter(grid)
        return counter.count()

